insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('a6c2f7af-1cb4-4f61-8633-d2cd160aec92', 'N5', 'N（thời gian）までに', '(Làm gì đó) trước thời điểm', 'までに khác まで: までに = hạn chót phải xong trước; まで = kéo dài liên tục đến lúc đó', 'N(thời điểm) + までに + V', 'Chỉ thời hạn chót, hành động phải hoàn thành trước hoặc đúng lúc đó', NULL, 'Phân biệt với まで (kéo dài liên tục đến — vd 8時まで働きます = làm việc liên tục đến 8 giờ).', NULL, '{}', NULL, 43, 'N（thời gian）までに', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('7e444045-35ec-44a7-b745-17d33a355058', 'N5', 'N／V ことができます', 'Có thể làm gì／Làm được gì (khả năng)', 'V(thể từ điển)+ことができます hoặc N+ができます', '① V(thể từ điển) + ことができます ② N + が + できます', 'Diễn tả khả năng thực hiện được 1 hành động hoặc kỹ năng nào đó', NULL, 'Có thể thêm phó từ bổ sung mức độ: すこし、ちょっと、だいたい、ぜんぜん、よく、あまり… (giống わかります).', NULL, '{}', NULL, 43, 'N／V ことができます', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('c886f301-ff05-4aa8-8ff0-90e5bc41cc5b', 'N5', '趣味は何ですか（趣味は N／V ことです）', 'Sở thích của bạn là gì？→ Sở thích của tôi là ~', '趣味は+V(thể từ điển)+ことです — danh từ hóa động từ bằng こと', '趣味は何ですか。→ 私の趣味は + N／V(thể từ điển)ことです。', 'Hỏi và trả lời về sở thích cá nhân', NULL, NULL, NULL, '{"N／V ことができます"}', NULL, 43, '趣味は何ですか（趣味は N／V ことです）', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('b65d0088-ddac-40c3-94ba-fefc4e3e95a5', 'N5', 'V1る／N の／Lượng từ（khoảng thời gian）+ 前に、V2ます', 'Trước khi làm gì thì làm việc kia', 'V dùng thể từ điển (る), N dùng の, khoảng thời gian đứng thẳng trước 前に', NULL, NULL, NULL, NULL, NULL, '{"V1てから、V2ます"}', NULL, 43, 'V1る／N の／Lượng từ（khoảng thời gian）+ 前に、V2ます', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('55cc9a2b-acab-4ddc-aa01-3753731797c4', 'N5', 'なかなか + Thể phủ định', 'Mãi mà không...(dù cố gắng nhưng chưa đạt được)', 'なかなか + phủ định = mãi không; なかなか + khẳng định = rất, hơn mức bình thường', 'なかなか + V(thể phủ định)／Aい・Aな(thể phủ định)', 'Diễn tả 1 việc mãi chưa đạt được dù đã cố gắng nhiều', NULL, 'なかなか + thể khẳng định = mang nghĩa "rất", vượt mức bình thường (khác nghĩa với khi đi cùng phủ định).', NULL, '{}', NULL, 43, 'なかなか + Thể phủ định', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('616171cb-18c6-437e-8a7b-8b23c19dc024', 'N5', 'ぜひ、V てください／ぜひ、V たいです', 'Nhất định hãy.../Rất muốn...', 'ぜひ nhấn mạnh mức độ mong muốn/yêu cầu, luôn đi cùng câu chỉ nguyện vọng hoặc yêu cầu', 'ぜひ + V(thể て) + ください ； ぜひ + V(bỏ ます) + たいです', 'Nhấn mạnh mức độ của 1 lời mời/yêu cầu hoặc nguyện vọng cá nhân', NULL, 'Chỉ dùng kèm câu chỉ nguyện vọng/yêu cầu để nhấn mạnh ý nghĩa đó, không dùng đơn lẻ.', NULL, '{}', NULL, 43, 'ぜひ、V てください／ぜひ、V たいです', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('5f73e6b0-6695-48e2-97c6-6b6320eff21a', 'N5', '動詞た形（thể た = ました）', 'Thể た (thể quá khứ thông thường), tương đương ～ました', 'Cách chia hoàn toàn giống thể て, chỉ thay て/で bằng た/だ', 'Nhóm I: う,つ,る→った｜む,ぶ,ぬ→んだ｜す→した｜く→いた｜ぐ→いだ ； Nhóm II: bỏ る thêm た ； Nhóm III: する→した, くる→きた', 'Dạng quá khứ thông thường của động từ, làm nền cho các mẫu như たことがあります/たり/たら', 'thông thường (không lịch sự)', NULL, NULL, '{"Thể て của động từ"}', NULL, 43, '動詞た形（thể た = ました）', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('62cc9049-e1a6-403f-bde9-92b498d9b16d', 'N5', 'V たことがあります／ありません', 'Đã từng làm gì／Chưa từng làm gì', 'たことがあります = kinh nghiệm đã từng trải qua', 'V(thể た) + ことがあります／ありません', 'Diễn tả kinh nghiệm đã từng (hoặc chưa từng) trải qua 1 việc gì đó', NULL, NULL, NULL, '{}', NULL, 44, 'V たことがあります／ありません', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('34fd6dbf-4f2b-442b-8c8e-e31d33032256', 'N5', 'V たり、V たりします', 'Liệt kê vài hành động tiêu biểu trong 1 nhóm hành động (không quan tâm thứ tự)', 'たり…たりします — chỉ liệt kê vài ví dụ tiêu biểu, không đầy đủ, không theo thứ tự', 'V1(thể た, bỏ た/だ thêm り) + V2(thể た, bỏ た/だ thêm り) + します', 'Liệt kê một vài hành động tiêu biểu trong 1 khoảng thời gian, không nhấn mạnh trình tự thực hiện', NULL, 'Thì (hiện tại/quá khứ) được chia ở động từ cuối cùng (します/しました).', 'Khác V1て、V2て (liệt kê đầy đủ, có thứ tự) — たり chỉ nêu vài ví dụ tiêu biểu, không quan tâm thứ tự.', '{"V1て、V2て、～Vます"}', NULL, 44, 'V たり、V たりします', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('567747e9-1802-45d1-bf24-0ab85d1b90f8', 'N5', 'Aい → くなります／Aな → になります／N → になります', 'Trở nên／Trở thành...', 'Aい bỏ い thêm くなります; Aな/N thêm になります trực tiếp', 'Aい → Aくなります ； Aな／N → Aに／Nに + なります', 'Diễn tả sự thay đổi trạng thái/tính chất theo thời gian, trở nên như thế nào', NULL, NULL, NULL, '{}', NULL, 44, 'Aい → くなります／Aな → になります／N → になります', 'pdf', 'ok')
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('bd8cb060-8b17-4085-8158-d083e8546228', '7e444045-35ec-44a7-b745-17d33a355058', 1, 'V(thể từ điển) + ことができます — có thể thực hiện hành động', 'V(thể từ điển) + ことができます', 'Diễn tả khả năng thực hiện 1 hành động cụ thể', NULL, 43, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('8d865555-c898-44b2-a8ef-175f8ab25eaa', '7e444045-35ec-44a7-b745-17d33a355058', 2, 'N + が + できます — có kỹ năng/khả năng làm N', 'N + が + できます', 'Diễn tả có kỹ năng hoặc khả năng làm được 1 việc/môn (danh từ hóa)', NULL, 43, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('30e97135-66c4-4509-94e1-202b19d34f7d', 'b65d0088-ddac-40c3-94ba-fefc4e3e95a5', 1, 'V(thể từ điển) + まえに — trước khi làm V', 'V(thể từ điển) + まえに、V2ます', 'V1 chưa xảy ra, xảy ra sau V2 theo trình tự thời gian ngược', NULL, 43, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('8bce101c-dcfc-455a-8d75-bb7f7eb7627d', 'b65d0088-ddac-40c3-94ba-fefc4e3e95a5', 2, 'N + の + まえに — trước N (danh từ)', 'N + の + まえに、V2ます', 'Chỉ thời điểm trước 1 sự kiện/danh từ cụ thể', NULL, 43, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('b0b1006f-4e1c-40f9-b401-caa7c2df1d2e', 'b65d0088-ddac-40c3-94ba-fefc4e3e95a5', 3, 'Lượng từ（khoảng thời gian）+ まえに — cách đây X thời gian', 'Lượng từ(khoảng thời gian) + まえに', 'Chỉ mốc thời gian tính từ hiện tại lùi về quá khứ', NULL, 43, 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('a6c2f7af-1cb4-4f61-8633-d2cd160aec92', NULL, 1, 'standard', 'レポートは5時までに送らなければなりません。', 'Phải nộp báo cáo trước 5 giờ.', 'レポートは5時＿＿＿送らなければなりません。', 'までに', 'pdf');
