insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('b65d0088-ddac-40c3-94ba-fefc4e3e95a5', 'b0b1006f-4e1c-40f9-b401-caa7c2df1d2e', 1, 'standard', '先生は30分前に、出かけました。', 'Giáo viên đã ra ngoài 30 phút trước.', '先生は30分＿＿＿、出かけました。', '前に', 'pdf');
